program.compute:
options=read('/input/options')
goal_min=goal['min_count']
goal_max=goal['max_count']
goal_sum_bounds=goal.get('sum_bounds',{})
goal_unique=goal.get('unique',[])
goal_order_by=goal.get('order_by',[])
from itertools import combinations

# We cannot import itertools, so use combinations from builtins

# Prepare list of option dicts
opts=options

# Helper to check unique fields
 def unique_fields_ok(selection):
  for field in goal_unique:
   vals=[opt[field] for opt in selection]
   if len(vals)!=len(set(vals)):
    return False
  return True

# Helper to check sum bounds
 def sum_bounds_ok(selection):
  for field,bounds in goal_sum_bounds.items():
   s=sum(opt.get(field,0) for opt in selection)
   if 'min' in bounds and s<bounds['min']:
    return False
   if 'max' in bounds and s>bounds['max']:
    return False
  return True

# Helper to check cover (empty here)
 def cover_ok(selection):
  # No cover constraints given
  return True

# Helper to check requires (closed_dependencies)
 def closed_dependencies_ok(selection):
  if not goal.get('closed_dependencies',False):
   return True
  ids=set(opt['id'] for opt in selection)
  for opt in selection:
   for req in opt.get('requires',[]):
    if req not in ids:
     return False
  return True

# Helper to check conflicts
 def no_conflicts_ok(selection):
  if not goal.get('no_conflicts',False):
   return True
  ids=set(opt['id'] for opt in selection)
  for opt in selection:
   for c in opt.get('conflicts',[]):
    if c in ids:
     return False
  return True

# Check all goal constraints
 def valid(ids):
  if len(ids)<goal_min or len(ids)>goal_max:
   return False
  selection=[opt for opt in opts if opt['id'] in ids]
  if not unique_fields_ok(selection):
   return False
  if not sum_bounds_ok(selection):
   return False
  if not cover_ok(selection):
   return False
  if not closed_dependencies_ok(selection):
   return False
  if not no_conflicts_ok(selection):
   return False
  return True

# Sort options by order_by keys ascending
 def sort_key(opt):
  return tuple(opt[k] for k in goal_order_by)

opts_sorted=sorted(opts,key=sort_key)

result=None

for k in range(goal_min,goal_max+1):
 for comb in combinations(opts_sorted,k):
  ids=[opt['id'] for opt in comb]
  if valid(ids):
   result=ids
   break
 if result is not None:
  break

if result is None:
 result=[]

program.effects:
existing=read('/output/selection')
if existing is None or not valid(existing):
 if len(result)>0:
  write('/output/selection',result)
  send('report','team',result)
 else:
  # no valid selection found, do not write or send
  pass
else:
 # existing valid selection present
 status_report=status('report')
 if status_report!='sent':
  send('report','team',existing)

if exists('/tmp/cache'):
 delete('/tmp/cache')

